import React, { useState, useEffect } from 'react';
import { getLatestReadings, getSensorStats, getRecentAlerts, getAlertStats } from '../api/api';

// This function makes the date look nice like "Jan 15, 10:30 AM"
function formatTime(isoString) {
  if (isoString == null || isoString == "") {
    return 'N/A';
  }
  let myDate = new Date(isoString);
  return myDate.toLocaleString('en-US', {
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
}

// A small box for each sensor
function SensorCard(props) {
  let reading = props.reading; // Getting the data from props

  return (
    <div className="sensor-card">
      <div className="sensor-card-header">
        <div>
          <div className="sensor-topic">{reading.topic}</div>
          <div className="sensor-time">Last seen: {formatTime(reading.received_at)}</div>
        </div>
        <span className="badge badge-ok">ONLINE</span>
      </div>

      <div className="sensor-values">
        {/* If temperature exists, show it */}
        {reading.temperature != null ? (
          <div className="sensor-value-item">
            <div className="sensor-value-label">🌡️ Temp</div>
            <div className="sensor-value-number">
              {reading.temperature.toFixed(1)}
              <span className="sensor-value-unit">°C</span>
            </div>
          </div>
        ) : null}

        {/* If humidity exists, show it */}
        {reading.humidity != null ? (
          <div className="sensor-value-item">
            <div className="sensor-value-label">💧 Humidity</div>
            <div className="sensor-value-number">
              {reading.humidity.toFixed(1)}
              <span className="sensor-value-unit">%</span>
            </div>
          </div>
        ) : null}

        {/* I am doing the same for the others below... */}
        {reading.voltage != null ? (
          <div className="sensor-value-item">
            <div className="sensor-value-label">⚡ Voltage</div>
            <div className="sensor-value-number">{reading.voltage.toFixed(1)}V</div>
          </div>
        ) : null}
      </div>
    </div>
  );
}

function Dashboard() {
  const [latestReadings, setLatestReadings] = useState([]);
  const [sensorStats, setSensorStats] = useState(null);
  const [recentAlerts, setRecentAlerts] = useState([]);
  const [alertStats, setAlertStats] = useState(null);
  const [loading, setLoading] = useState(true);

  // This function gets all the data from the server
  async function loadDashboardData() {
    setLoading(true);

    try {
      // Getting data one by one
      const readingsResponse = await getLatestReadings();
      setLatestReadings(readingsResponse.data);

      const statsResponse = await getSensorStats();
      setSensorStats(statsResponse);

      const alertsResponse = await getRecentAlerts(5);
      setRecentAlerts(alertsResponse.data);

      const alertStatsResponse = await getAlertStats();
      setAlertStats(alertStatsResponse);

    } catch (err) {
      alert("Something went wrong with the data!");
    }

    setLoading(false);
  }

  useEffect(function() {
    loadDashboardData();
    // Refresh every 30 seconds
    const myInterval = setInterval(loadDashboardData, 30000);
    return () => clearInterval(myInterval);
  }, []);

  if (loading == true) {
    return <div className="loading-text">⏳ Loading dashboard data...</div>;
  }

  return (
    <div>
      <div className="page-header">
        <h2 className="page-title">Dashboard Overview</h2>
        <button className="refresh-btn" onClick={loadDashboardData}>Refresh</button>
      </div>

      <div className="stats-grid">
        <div className="stat-card blue">
          <div className="stat-label">Total Readings</div>
          <div className="stat-value">{sensorStats ? sensorStats.total_readings : 0}</div>
        </div>
        <div className="stat-card green">
          <div className="stat-label">Active Devices</div>
          <div className="stat-value">{sensorStats ? sensorStats.total_topics : 0}</div>
        </div>
      </div>

      <div className="card">
        <div className="card-title">Latest Sensor Readings</div>
        <div className="sensors-grid">
          {latestReadings.map(function(item) {
            return <SensorCard key={item.id} reading={item} />;
          })}
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
